#include <stdio.h>
int main(void){char op;int a,b; printf("Enter operator (+, -, *, /, %%): "); scanf(" %c",&op); printf("Enter two integers: "); scanf("%d %d",&a,&b); switch(op){case '+':printf("Result: %d + %d = %d\n",a,b,a+b);break;case '-':printf("Result: %d - %d = %d\n",a,b,a-b);break;case '*':printf("Result: %d * %d = %d\n",a,b,a*b);break;case '/':if(b)printf("Result: %d / %d = %d\n",a,b,a/b);else puts("Error: Division by zero is not allowed.");break;case '%':if(b)printf("Result: %d %% %d = %d\n",a,b,a%b);else puts("Error: Division by zero is not allowed.");break;default:puts("Error: Invalid operator.");} return 0;}
